/**
 * The ground under each landmark's setting (lane D2, D2-09). GENERATED by scripts/opus-sf/assets/landmark-settings.ts
 * from the published city: do not edit by hand; re-run it after changing a landmark's exclusion, sink, base or position
 * (tests/opus-bay-sf-landmark-context re-measures a few rows). Per landmark:
 *   base     its base (world y) exactly as the renderer computes it (numeric, or the chunk's 'terrain' base + baseLift)
 *   sink     the city ground's sink inside its exclusion (world/sf/sites.ts)
 *   grid     the DRAWN city ground on a LOCAL grid over the exclusion's bounds + 1 u (x0, z0, step, cols × rows,
 *            row-major, 1/100 u above the base; each point the highest ground within ±0.5 u)
 *   streets  the city streets the exclusion clips: ROAD_CLASSES name, right-of-way (u), the centreline in LOCAL
 *            x, y, z triples (y above the base: the street's own height at the exclusion edge, the sunk ground 2 u in)
 */
export interface SettingData {
  base: number;
  sink: number;
  grid: { x0: number; z0: number; step: number; cols: number; rows: number; h: readonly number[] };
  streets: readonly { c: string; w: number; p: readonly number[] }[];
}

